import { InjectionToken } from "@angular/core";
import { CreateItemFields, CreateListFields, List, UpdateItemFields, UpdateListFields } from "../models/list.model";
import { Observable } from "rxjs";

export const DATA_REPOSITORY = new InjectionToken<DataRepository>('DataRepository');

export class DataRepositoryState {
  isDbOpen = false;
  error: string | null = null;
}

export interface DataRepository {
  getState(): DataRepositoryState;

  createItemInList(listId: string, newitem: CreateItemFields): Observable<string>;
  updateItem(id: string, item: UpdateItemFields): Observable<number>;
  deleteItem(id: string): Observable<void>;

  createList(param: CreateListFields): Observable<string>;
  getAllLists(): Observable<List[]>;
  getListById(id: string): Observable<List>;
  updateList(id: string, list: UpdateListFields): Observable<number>;
  deleteList(id: string): Observable<void>;
}
